// BootQuest kata module: a TESTABLE, self-contained adaptation (not a repo file) of netslack @ c7337d7:
//   src/NetSlack.Domain/Workspaces/Workspace.cs (Create + NormalizeSlug, verbatim rule),
//   src/NetSlack.Application/Workspaces/WorkspaceService.cs:22-59 (CreateAsync: pre-check, insert, recovery),
//   src/NetSlack.Domain/Common/Guard.cs and src/NetSlack.Application/Common/AppException.cs.
// EF Core is replaced by an in-memory store that enforces the unique index on Workspaces.Slug and
// throws a DbUpdateException stand-in on a violating save; the channel, membership and the current
// user are left out. The slug rules and the service's control flow are copied verbatim.
namespace NetSlack.Kata;

public static class Guard
{
    public static string AgainstEmpty(string value, string parameterName, int maxLength)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new ArgumentException($"{parameterName} is required.", parameterName);
        }

        var trimmed = value.Trim();
        if (trimmed.Length > maxLength)
        {
            throw new ArgumentException($"{parameterName} cannot exceed {maxLength} characters.", parameterName);
        }

        return trimmed;
    }
}

public abstract class AppException(string message) : Exception(message);

public sealed class ConflictException(string message) : AppException(message);

/// <summary>Stand-in for EF Core's DbUpdateException (here: a unique-index violation on save).</summary>
public sealed class DbUpdateException(string message) : Exception(message);

public sealed class Workspace
{
    private Workspace(string name, string slug)
    {
        Name = name;
        Slug = slug;
    }

    public string Name { get; }

    public string Slug { get; }

    public static Workspace Create(string name, string slug) =>
        new(Guard.AgainstEmpty(name, nameof(name), 120), NormalizeSlug(slug));

    private static string NormalizeSlug(string slug)
    {
        var normalized = Guard.AgainstEmpty(slug, nameof(slug), 64)
            .ToLowerInvariant()
            .Replace(' ', '-');

        if (normalized.Any(character => !char.IsLetterOrDigit(character) && character != '-'))
        {
            throw new ArgumentException("Workspace slug can only contain letters, numbers, and dashes.", nameof(slug));
        }

        return normalized;
    }
}

public sealed record CreateWorkspaceCommand(string Name, string Slug);

/// <summary>The Workspaces table: saved rows + rows added since the last save.</summary>
public sealed class WorkspaceSet
{
    internal readonly List<Workspace> Saved = [];
    internal readonly List<Workspace> Pending = [];

    public WorkspaceSet AsNoTracking() => this;

    public Task<bool> AnyAsync(Func<Workspace, bool> predicate, CancellationToken cancellationToken) =>
        Task.FromResult(Saved.Any(predicate));

    public void Add(Workspace workspace) => Pending.Add(workspace);

    public IReadOnlyList<string> Slugs => Saved.Select(w => w.Slug).ToList();
}

public sealed class AppDb
{
    public WorkspaceSet Workspaces { get; } = new();

    /// <summary>Unique index IX_Workspaces_Slug: a second row with the same stored slug fails the save.</summary>
    public Task SaveChangesAsync(CancellationToken cancellationToken)
    {
        var batch = Workspaces.Pending.ToList();
        Workspaces.Pending.Clear();
        foreach (var w in batch)
        {
            if (Workspaces.Saved.Any(s => s.Slug == w.Slug))
            {
                throw new DbUpdateException($"UNIQUE constraint failed: Workspaces.Slug ('{w.Slug}')");
            }
        }

        Workspaces.Saved.AddRange(batch);
        return Task.CompletedTask;
    }
}

public sealed class WorkspaceService(AppDb db)
{
    public async Task<Workspace> CreateAsync(CreateWorkspaceCommand command, CancellationToken cancellationToken)
    {
        var slug = command.Slug.Trim().ToLowerInvariant().Replace(' ', '-');
        var slugExists = await db.Workspaces.AnyAsync(workspace => workspace.Slug == slug, cancellationToken);
        if (slugExists)
        {
            throw new ConflictException($"Workspace slug '{slug}' is already taken.");
        }

        var workspace = Workspace.Create(command.Name, command.Slug);

        db.Workspaces.Add(workspace);
        try
        {
            await db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException)
        {
            // A concurrent writer can win after the pre-check. Ask the database for
            // the normalized slug; this avoids parsing provider-specific constraint
            // names and avoids turning unrelated unique violations into conflicts.
            var existsAfterSave = await db.Workspaces
                .AsNoTracking()
                .AnyAsync(existing => existing.Slug == slug, cancellationToken);
            if (existsAfterSave)
            {
                throw new ConflictException($"Workspace slug '{slug}' is already taken.");
            }

            throw;
        }

        return workspace;
    }
}

