using NetSlack.Kata;

public sealed class WorkspaceSlugTests
{
    private static Task<Workspace> Create(WorkspaceService service, string name, string slug) =>
        service.CreateAsync(new CreateWorkspaceCommand(name, slug), CancellationToken.None);

    [Fact(DisplayName = "Duplicate_workspace_slug_is_reported_as_conflict (ported from tests/NetSlack.Application.Tests/WorkflowTests.cs:66)")]
    public async Task Duplicate_workspace_slug_is_reported_as_conflict()
    {
        var service = new WorkspaceService(new AppDb());

        await Create(service, "First", "same-slug");
        await Assert.ThrowsAsync<ConflictException>(() => Create(service, "Second", "same-slug"));
    }

    [Fact(DisplayName = "User_can_create_workspace: the slug is stored as given (ported from tests/NetSlack.Application.Tests/WorkflowTests.cs:16, assertion :37)")]
    public async Task User_can_create_workspace()
    {
        var workspace = await Create(new WorkspaceService(new AppDb()), "NetSlack", "netslack");

        Assert.Equal("netslack", workspace.Slug);
    }

    [Fact(DisplayName = "'acme--co' next to 'acme-co' is a conflict or a new workspace, never a raw DbUpdateException 500 (review finding A, astraupskill/06-SOLUTIONS-AND-REVIEW.md:17)")]
    public async Task NearDuplicateSlug_NeverEscapesAsDbUpdateException()
    {
        var db = new AppDb();
        var service = new WorkspaceService(db);
        await Create(service, "Acme", "acme-co");

        var thrown = await Record.ExceptionAsync(() => Create(service, "Acme again", "acme--co"));

        Assert.True(thrown is null || thrown is ConflictException, $"pre-check, insert and recovery disagree on the slug: {thrown?.GetType().Name}: {thrown?.Message}");
    }

    [Fact(DisplayName = "'Acme  Co' (two spaces) next to 'acme-co' is a conflict or a new workspace, never a raw DbUpdateException 500 (review finding A)")]
    public async Task DoubleSpaceSlug_NeverEscapesAsDbUpdateException()
    {
        var service = new WorkspaceService(new AppDb());
        await Create(service, "Acme", "acme-co");

        var thrown = await Record.ExceptionAsync(() => Create(service, "Acme Co", "Acme  Co"));

        Assert.True(thrown is null || thrown is ConflictException, $"pre-check, insert and recovery disagree on the slug: {thrown?.GetType().Name}: {thrown?.Message}");
    }

    [Fact(DisplayName = "a space becomes a dash: 'Acme Co' conflicts with an existing 'acme-co'")]
    public async Task SpaceSlug_ConflictsWithDashSlug()
    {
        var service = new WorkspaceService(new AppDb());
        await Create(service, "Acme", "acme-co");

        await Assert.ThrowsAsync<ConflictException>(() => Create(service, "Acme Co", "Acme Co"));
    }
}
